func (this *Text) DeprocessText(text []uint16, start int32, end int32) []uint16 {
	if text == (nil) {
		return make([]uint16, 0)
	}
	if start < 0 {
		start = 0
	}
	var length int32 = int32(len(text))
	if end == -1 {
		end = start + length
	}
	if this.segments != (nil) && end > this.segments[0] {
		var nSegments int32 = int32(len(this.segments))
		if nSegments > 0 && start <= this.segments[nSegments-1] {
			var nLeadSegments int32 = 0
			for start-nLeadSegments > this.segments[nLeadSegments] {
				nLeadSegments++
			}
			var segmentCount int32 = nLeadSegments
			for i := int32(start); i < end; i++ {
				if segmentCount < nSegments && i-segmentCount == this.segments[segmentCount] {
					segmentCount++
				} else {
					text[i-segmentCount+nLeadSegments-start] = text[i-start]
				}
			}
			length = end - start - segmentCount + nLeadSegments
		}
	}
	if start != 0 || end != start+length {
		var newText []uint16 = make([]uint16, length)
		copy(newText[0:], text[0:0+length])
		return newText
	}
	return text
}

